patterns=[r'\*\s*Decoder\s*=', r'DecodeComplete\s*=', r'\*\s*DecodeComplete\s*=']
for pat in patterns:
    print('PATTERN', pat)
    rx=re.compile(pat)
    cnt=0
    for dirpath, dirs, files in os.walk(os.path.join(root,'arch')):
        for fn in files:
            if fn.endswith(('.c','.h','.inc')):
                p=os.path.join(dirpath,fn)
                try: txt=open(p,'r',errors='ignore').read().splitlines()
                except TypeError:
                    txt=open(p,'r').read().splitlines()
                for i,line in enumerate(txt,1):
                    if rx.search(line):
                        print(os.path.relpath(p,root)+':%d:%s'%(i,line.strip()))
                        cnt+=1
                        if cnt>100: break
                if cnt>100: break
        if cnt>100: break
    print('count shown', cnt)

